21. async function request<T>(path: string, init?: RequestInit): Promise<T> {
22.   const response = await fetch(`${API_BASE_URL}${path}`, {
23.     ...init,
24.     headers: { "Content-Type": "application/json", ...init?.headers },
25.   });
26.   const body = (await response.json().catch(() => null)) as
27.     | { error?: { code?: string; message?: string } }
28.     | null;
29.   if (!response.ok) {
30.     throw new ApiError(
31.       response.status,
32.       body?.error?.code ?? "request_failed",
33.       body?.error?.message ?? "The request could not be completed.",
34.     );
35.   }
36.   return body as T;
37. }
